(()=>{'use strict';const root=document.querySelector('.insurance-index');if(!root)return;const products=[["grazhdanska-otgovornost","Гражданска отговорност","Подновявате полица или застраховате автомобил за първи път? Ще сравним офертите и ще уточним важните подробности заедно."],["kasko","Каско","Разкажете ни за колата си. Ще обсъдим покритието, сервиза и условията, на които държите."],["imushtestveni","Имуществени","За дома, магазина или офиса ви. Нека видим какво искате да включите и от какви рискове да го защитите."],["meditsinski","Медицински","За вас, семейството или екипа. Ще поговорим за медицинските услуги, периода и плановете ви за пътуване."],["zhivot","Живот","Когато мислите за близките си, е добре да има с кого да обсъдите възможностите. Ние ще ви изслушаме."],["pensionni","Пенсионни","Нека отделим време за плановете ви след работа и да разгледаме възможностите за пенсионно осигуряване."]],tabs=[...root.querySelectorAll('[data-product]')],panel=root.querySelector('.index-stage');function select(i,focus=false){const p=products[i];tabs.forEach((t,n)=>{t.setAttribute('aria-selected',String(i===n));t.tabIndex=i===n?0:-1});panel.setAttribute('aria-labelledby',tabs[i].id);const img=panel.querySelector('img');img.src='/assets/'+p[0]+'-cutout.webp';img.alt=p[1]+' — илюстрация';panel.querySelector('h3').textContent=p[1];panel.querySelector('p').textContent=p[2];panel.querySelector('a').href='/'+p[0]+'/';if(focus)tabs[i].focus()}tabs.forEach((t,i)=>{t.addEventListener('click',()=>{select(i);{const cap=panel.querySelector('.stage-caption'),r=cap.getBoundingClientRect(),cs=getComputedStyle(cap),block=r.bottom+parseFloat(cs.scrollMarginBottom)>innerHeight?(matchMedia('(max-width:760px)').matches?'start':'end'):r.top<(parseFloat(getComputedStyle(document.documentElement).scrollPaddingTop)||0)+parseFloat(cs.scrollMarginTop)?'start':'';if(block)cap.scrollIntoView({block,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'})}});t.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight'||e.key==='ArrowDown')n=(i+1)%tabs.length;if(e.key==='ArrowLeft'||e.key==='ArrowUp')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();select(n,true)}})});const images=[];const preload=()=>products.forEach(p=>{const image=new Image();image.src='/assets/'+p[0]+'-cutout.webp';images.push(image)});if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){preload();observer.disconnect()}},{rootMargin:'200px'});observer.observe(root)}const row=document.querySelector('.site-header .header-inner');const sync=()=>{const header=row.closest('.site-header');const border=parseFloat(getComputedStyle(header).borderBottomWidth)||0;document.documentElement.style.setProperty('--insurance-header-height',(row.getBoundingClientRect().height+border)+'px')};sync();if('ResizeObserver'in window)new ResizeObserver(sync).observe(row);else window.addEventListener('resize',sync);document.fonts.ready.then(()=>{sync();if(location.hash==='#insurance')root.scrollIntoView({block:'start',behavior:'instant'})});})();